// Domain layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Pure functions only: no network, storage or DOM.

export function asText(v) {
  return String(v);
}

export function moneyCompact(v) {
  const n = Number(v);
  const units = [
    [1e9, "B"],
    [1e6, "M"],
    [1e3, "K"],
  ];
  for (const [size, suffix] of units) {
    if (Math.abs(n) >= size) return "$" + (n / size).toFixed(1) + suffix;
  }
  return "$" + n.toFixed(0);
}

export function percent(v) {
  return (Number(v) * 100).toFixed(1) + "%";
}

export function dateShort(v) {
  const d = new Date(v);
  const m = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return d.getUTCDate() + " " + m[d.getUTCMonth()] + " " + d.getUTCFullYear();
}

// Rows for the "deals" list, sort by value descending.
export function toDealRows(items) {
  return [...items]
    .sort((a, b) => {
      const x = a.value,
        y = b.value;
      const c =
        typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y));
      return -c;
    })
    .map((item) => ({
      id: item.id,
      name: asText(item.name),
      account: asText(item.account),
      value: moneyCompact(item.value),
      margin: percent(item.margin),
      closeOn: dateShort(item.closeOn),
    }));
}

// "dealCount" = count. Design showed "6".
export function dealCount(items) {
  return asText(items.length);
}

// "pipeline" = sum(value), shown as moneyCompact. Design showed "$453.1M".
export function pipeline(items) {
  return moneyCompact(items.reduce((s, x) => s + Number(x.value), 0));
}

// "avgDeal" = average(value), shown as moneyCompact. Design showed "$75.5M".
export function avgDeal(items) {
  return moneyCompact(
    items.length ? items.reduce((s, x) => s + Number(x.value), 0) / items.length : 0,
  );
}

// "largest" = max(value), shown as moneyCompact. Design showed "$152.5M".
export function largest(items) {
  return moneyCompact(items.length ? Math.max(...items.map((x) => Number(x.value))) : 0);
}

// "smallest" = min(value), shown as moneyCompact. Design showed "$9.8M".
export function smallest(items) {
  return moneyCompact(items.length ? Math.min(...items.map((x) => Number(x.value))) : 0);
}

// "avgMargin" = average(margin), shown as percent. Design showed "28.8%".
export function avgMargin(items) {
  return percent(items.length ? items.reduce((s, x) => s + Number(x.margin), 0) / items.length : 0);
}

