export function findDeal(items, id) {
  return items.find((item) => item.id === id) ?? null;
}

// Form text -> the types the API expects (taken from the example request body).
export function toDealInput(values) {
  return {
    name: String(values.name ?? "").trim(),
    account: String(values.account ?? "").trim(),
    value: Number(values.value),
    margin: Number(values.margin),
    notes: String(values.notes ?? "").trim(),
  };
}

// Raw values to prefill the form when an item is selected.
export function toFormValues(item) {
  if (!item) return {};
  return {
    name: item.name,
    account: item.account,
    value: item.value,
    margin: item.margin,
    notes: item.notes,
  };
}
